def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    result = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            result = mid
            hi = mid - 1  # continue left
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return result

def parse_duration(s):
    if not isinstance(s, str) or s == "":
        raise ValueError("empty duration")
    units = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    rank = {"d": 0, "h": 1, "m": 2, "s": 3}
    total = 0
    i = 0
    last_rank = -1
    seen = set()
    while i < len(s):
        start = i
        while i < len(s) and "0" <= s[i] <= "9":
            i += 1
        if start == i:
            raise ValueError("missing number")
        value = int(s[start:i])
        if i >= len(s):
            raise ValueError("missing unit")
        unit = s[i]
        if unit not in units:
            raise ValueError("bad unit")
        if unit in seen or rank[unit] <= last_rank:
            raise ValueError("duplicate or out of order")
        seen.add(unit)
        last_rank = rank[unit]
        total += value * units[unit]
        i += 1
    return total

