def summarize_sessions(events):
    totals = {}
    for event in events:
        user, seconds = event
        if seconds is None or seconds < 0:
            seconds = 0
        totals[user] = totals.get(user, 0) + seconds
    rows = [[user, total] for user, total in totals.items() if total > 0]
    rows.sort(key=lambda row: (-row[1], row[0]))
    return rows

